let instance: RetellAIClient | null = null;

export function getRetell AIClient(): RetellAIClient {
  if (!instance) {
    instance = new RetellAIClient({
      apiKey: process.env.RETELLAI_API_KEY!,
      // Additional options
    });
  }
  return instance;
